const releasePromotionRedemptions = `-- name: ReleasePromotionRedemptions :many
UPDATE promotion_redemptions SET status = 'RELEASED' WHERE booking_id = $1 AND status = 'HELD' RETURNING promotion_id
`

func (q *Queries) ReleasePromotionRedemptions(ctx context.Context, bookingID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, releasePromotionRedemptions, bookingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var promotion_id uuid.UUID
		if err := rows.Scan(&promotion_id); err != nil {
			return nil, err
		}
		items = append(items, promotion_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reservePromotionQuota = `-- name: ReservePromotionQuota :execrows
UPDATE promotions SET used_count = used_count + 1, updated_at = now()
WHERE id = $1 AND status = 'ACTIVE' AND (quota IS NULL OR used_count < quota)
`

func (q *Queries) ReservePromotionQuota(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, reservePromotionQuota, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

